public class LocalRunSettings:Form {
 readonly CheckedListBox scope=new CheckedListBox();readonly ComboBox backend=new ComboBox(),device=new ComboBox();readonly NumericUpDown layers=new NumericUpDown(),threads=new NumericUpDown();readonly LocalRun run;readonly Label note=new Label();readonly SleekButton save=new SleekButton(),setup=new SleekButton();bool busy;
 public LocalRunSettings(LocalRun value,Color bg,Color card,Color text,Color accent){run=value;Text="Run settings · "+run.Name;ClientSize=new Size(580,560);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;StartPosition=FormStartPosition.CenterParent;BackColor=bg;ForeColor=text;Font=new Font("Segoe UI",10);
  var options=LocalTranslation.Options(run);Controls.Add(new Label{Text="Covered text & execution",Location=new Point(24,20),Size=new Size(530,35),Font=new Font(Font,FontStyle.Bold)});
  Controls.Add(new Label{Text="Only sources already covered by our English overlay are eligible.",Location=new Point(24,61),Size=new Size(530,25)});
  scope.SetBounds(24,95,530,116);scope.BackColor=card;scope.ForeColor=text;scope.BorderStyle=BorderStyle.None;scope.CheckOnClick=true;foreach(string kind in LocalTranslation.Categories)scope.Items.Add(kind,options.Scope.Contains(kind));Controls.Add(scope);
  backend.DropDownStyle=ComboBoxStyle.DropDownList;backend.Items.AddRange(new object[]{"CPU","GPU · Vulkan","Hybrid · GPU layers + CPU remainder"});backend.SelectedIndex=options.Backend=="gpu"?1:options.Backend=="hybrid"?2:0;backend.SetBounds(24,243,530,30);Controls.Add(backend);
  device.DropDownStyle=ComboBoxStyle.DropDownList;device.Items.Add(new KeyValuePair<string,string>("","Automatic device"));device.DisplayMember="Value";device.SetBounds(24,288,530,30);Controls.Add(device);
  Controls.Add(new Label{Text="GPU layers (hybrid)",Location=new Point(24,335),Size=new Size(220,24)});layers.SetBounds(260,332,90,28);layers.Minimum=1;layers.Maximum=200;layers.Value=Math.Max(1,options.GpuLayers);Controls.Add(layers);
  Controls.Add(new Label{Text="CPU threads",Location=new Point(24,376),Size=new Size(220,24)});threads.SetBounds(260,372,90,28);threads.Minimum=1;threads.Maximum=Environment.ProcessorCount;threads.Value=Math.Max(1,Math.Min(Environment.ProcessorCount,options.Threads));Controls.Add(threads);
  note.SetBounds(24,416,530,70);note.Text="Completed work is kept. Changes apply after the current entry checkpoints. GPU/hybrid requires the optional Vulkan backend.";Controls.Add(note);
  setup.Text="Set up GPU backend";setup.SetBounds(24,503,200,36);setup.BackColor=card;setup.ForeColor=text;setup.Click+=async delegate{if(busy)return;busy=true;setup.Enabled=save.Enabled=false;try{await Task.Run(()=>LocalTranslation.Install(run.Model,true,CancellationToken.None));LoadDevices(options.Device);note.Text="Vulkan backend ready. Model weights were reused.";}catch(Exception e){note.Text=e.Message;}finally{busy=false;setup.Enabled=save.Enabled=true;}};Controls.Add(setup);
  save.Text="Save settings";save.Primary=true;save.BackColor=accent;save.ForeColor=text;save.SetBounds(374,503,180,36);save.Click+=delegate{try{var next=LocalTranslation.Options(run);next.Scope=scope.CheckedItems.Cast<string>().ToArray();next.Backend=backend.SelectedIndex==0?"cpu":backend.SelectedIndex==1?"gpu":"hybrid";next.GpuLayers=(int)layers.Value;next.Threads=(int)threads.Value;next.Device=((KeyValuePair<string,string>)device.SelectedItem).Key;LocalTranslation.SetOptions(run.Id,next);DialogResult=DialogResult.OK;}catch(Exception e){note.Text=e.Message;}};Controls.Add(save);AcceptButton=save;
  backend.SelectedIndexChanged+=delegate{layers.Enabled=backend.SelectedIndex==2;device.Enabled=backend.SelectedIndex>0;};layers.Enabled=backend.SelectedIndex==2;device.Enabled=backend.SelectedIndex>0;
  Shown+=async delegate{try{var rows=await Task.Run(()=>LocalBackend.Devices());if(IsDisposed)return;foreach(var row in rows)device.Items.Add(row);SelectDevice(options.Device);}catch(Exception e){note.Text="Device detection: "+e.Message;}};FormClosing+=delegate(object sender,FormClosingEventArgs e){if(busy){e.Cancel=true;note.Text="Finish GPU backend setup before closing this window.";}};
 }
 void SelectDevice(string wanted){foreach(var item in device.Items.Cast<KeyValuePair<string,string>>())if(item.Key==wanted){device.SelectedItem=item;return;}device.SelectedIndex=0;}
 void LoadDevices(string wanted){foreach(var item in LocalBackend.Devices())if(!device.Items.Cast<KeyValuePair<string,string>>().Any(x=>x.Key==item.Key))device.Items.Add(item);SelectDevice(wanted);}
}
public static class LocalBackend {
 public static List<KeyValuePair<string,string>> Devices(){var result=new List<KeyValuePair<string,string>>();string exe=LocalTranslation.RuntimeExe(true);if(!File.Exists(exe))return result;var start=new ProcessStartInfo(exe,"--list-devices"){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden,RedirectStandardOutput=true,RedirectStandardError=true,WorkingDirectory=Path.GetDirectoryName(exe)};using(var process=Process.Start(start)){var output=process.StandardOutput.ReadToEndAsync();var error=process.StandardError.ReadToEndAsync();if(!process.WaitForExit(12000)){process.Kill();throw new IOException("GPU device enumeration timed out.");}string text=output.Result+"\n"+error.Result;foreach(Match m in Regex.Matches(text,@"(?m)^\s*(Vulkan\d+):\s*(.+)$"))result.Add(new KeyValuePair<string,string>(m.Groups[1].Value,m.Groups[2].Value.Trim()));}return result;}
}

public class LocalTranslationEditor:Form {
 readonly LocalRun run;readonly TextBox search=new TextBox(),source=new TextBox(),target=new TextBox();readonly Label status=new Label();readonly CheckBox original=new CheckBox(),defer=new CheckBox();readonly DataGridView grid=new DataGridView();readonly SleekButton save=new SleekButton(),reset=new SleekButton(),refresh=new SleekButton();readonly System.Windows.Forms.Timer debounce=new System.Windows.Forms.Timer();
 List<LocalUnit> all=new List<LocalUnit>(),shown=new List<LocalUnit>();Dictionary<string,LocalResult> results=new Dictionary<string,LocalResult>();Dictionary<string,LocalEdit> edits=new Dictionary<string,LocalEdit>();Dictionary<string,string> failures=new Dictionary<string,string>();Dictionary<string,string> bySource=new Dictionary<string,string>();string[] selectedScope;LocalUnit current;bool busy;
 public LocalTranslationEditor(LocalRun value,Color bg,Color card,Color text,Color accent){run=value;Text="Translations · "+run.Name;ClientSize=new Size(1040,720);MinimumSize=new Size(820,620);BackColor=bg;ForeColor=text;Font=new Font("Segoe UI",10);StartPosition=FormStartPosition.CenterParent;
  search.PlaceholderTextCompat("Search source, translation, category or status");Controls.Add(search);search.TextChanged+=delegate{debounce.Stop();debounce.Start();};debounce.Interval=250;debounce.Tick+=delegate{debounce.Stop();Filter();};
  refresh.Text="Refresh";refresh.BackColor=card;refresh.ForeColor=text;refresh.Click+=async delegate{if(busy)return;busy=true;refresh.Enabled=false;try{await Task.Run(()=>{results=LocalTranslation.Results(run.Id);bySource=results.Values.GroupBy(x=>x.Source).Where(g=>g.Select(x=>x.Target).Distinct().Count()==1).ToDictionary(g=>g.Key,g=>g.First().Target);edits=LocalTranslation.Edits(run.Id);failures=LocalTranslation.Read<Dictionary<string,string>>(LocalTranslation.RunFile(run.Id,"failures.json"));selectedScope=LocalTranslation.Options(run).Scope;});grid.Invalidate();status.Text="Updated cached entries · select a row to read its latest translation";}catch(Exception e){status.Text=e.Message;}finally{busy=false;refresh.Enabled=true;}};Controls.Add(refresh);
  grid.VirtualMode=true;grid.ReadOnly=true;grid.AllowUserToAddRows=false;grid.AllowUserToDeleteRows=false;grid.RowHeadersVisible=false;grid.AutoGenerateColumns=false;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;grid.MultiSelect=false;grid.BackgroundColor=card;grid.BorderStyle=BorderStyle.None;grid.DefaultCellStyle.BackColor=card;grid.DefaultCellStyle.ForeColor=text;grid.DefaultCellStyle.SelectionBackColor=accent;grid.EnableHeadersVisualStyles=false;grid.ColumnHeadersDefaultCellStyle.BackColor=bg;grid.ColumnHeadersDefaultCellStyle.ForeColor=text;
  foreach(string name in new[]{"Status","Category","Source","Translation"})grid.Columns.Add(new DataGridViewTextBoxColumn{HeaderText=name,Width=name=="Status"?120:name=="Category"?110:360,SortMode=DataGridViewColumnSortMode.NotSortable});grid.CellValueNeeded+=delegate(object sender,DataGridViewCellValueEventArgs e){if(e.RowIndex>=shown.Count)return;var row=shown[e.RowIndex];e.Value=e.ColumnIndex==0?State(row):e.ColumnIndex==1?row.Category:e.ColumnIndex==2?Preview(row.Source):Preview(Target(row));};grid.CurrentCellChanged+=delegate{SelectRow();};Controls.Add(grid);
  foreach(var box in new[]{source,target}){box.Multiline=true;box.ScrollBars=ScrollBars.Vertical;box.WordWrap=true;box.BackColor=card;box.ForeColor=text;Controls.Add(box);}source.ReadOnly=true;
  original.Text="Leave original";defer.Text="Defer this entry";Controls.Add(original);Controls.Add(defer);Controls.Add(status);
  save.Text="Save edit";save.Primary=true;save.BackColor=accent;save.ForeColor=text;save.Click+=async delegate{await Save(false);};Controls.Add(save);reset.Text="Clear override";reset.BackColor=card;reset.ForeColor=text;reset.Click+=async delegate{await Save(true);};Controls.Add(reset);
  Resize+=delegate{Arrange();};Shown+=async delegate{busy=true;status.Text="Loading covered entries…";try{await Task.Run(()=>{var covered=EnglishSupport.CoveredLocalSources(run.Root);all=covered.Select(x=>new LocalUnit{Source=x.Key,Category=x.Value,Context="EnglishCoverage",Key=LocalTranslation.TextHash(x.Value+"\u001fEnglishCoverage\u001f"+x.Key)}).ToList();results=LocalTranslation.Results(run.Id);bySource=results.Values.GroupBy(x=>x.Source).Where(g=>g.Select(x=>x.Target).Distinct().Count()==1).ToDictionary(g=>g.Key,g=>g.First().Target);all.AddRange(results.Values.Where(x=>!covered.ContainsKey(x.Source)).GroupBy(x=>x.Source).Select(g=>g.First()).Cast<LocalUnit>());selectedScope=LocalTranslation.Options(run).Scope;edits=LocalTranslation.Edits(run.Id);failures=LocalTranslation.Read<Dictionary<string,string>>(LocalTranslation.RunFile(run.Id,"failures.json"));});Filter();}catch(Exception e){status.Text=e.Message;}finally{busy=false;}};FormClosed+=delegate{debounce.Stop();debounce.Dispose();};Arrange();
 }
 void Arrange(){int w=ClientSize.Width,h=ClientSize.Height;search.SetBounds(18,16,w-160,28);refresh.SetBounds(w-128,14,110,33);grid.SetBounds(18,58,w-36,Math.Max(160,h-310));source.SetBounds(18,h-238,(w-46)/2,148);target.SetBounds(source.Right+10,h-238,(w-46)/2,148);original.SetBounds(18,h-78,160,27);defer.SetBounds(185,h-78,170,27);save.SetBounds(w-290,h-77,120,34);reset.SetBounds(w-160,h-77,142,34);status.SetBounds(18,h-35,w-36,29);}
 static string Preview(string value){value=(value??"").Replace("\n"," ↵ ");return value.Length>500?value.Substring(0,500)+"…":value;}
 string Target(LocalUnit row){LocalEdit edit;if(edits.TryGetValue(row.Key,out edit)&&edit.Target!=null)return edit.Target;LocalResult result;if(results.TryGetValue(row.Key,out result))return result.Target;string translated;return bySource.TryGetValue(row.Source,out translated)?translated:"";}
 string State(LocalUnit row){if(row.Context!="EnglishCoverage")return "Inactive legacy";LocalEdit edit;if(edits.TryGetValue(row.Key,out edit)){if(edit.LeaveOriginal)return "Original";if(edit.Deferred)return "Deferred";if(edit.Target!=null)return "Edited";}if(!(selectedScope??run.Scope).Contains(row.Category))return "Excluded";if(Target(row)!="")return "Completed";return failures.ContainsKey(row.Key)?"Failed / deferred":"Pending";}
 void Filter(){string q=search.Text.Trim();shown=all.Where(x=>q.Length==0||x.Source.IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0||Target(x).IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0||x.Category.IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0||State(x).IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0).ToList();grid.RowCount=shown.Count;grid.Invalidate();status.Text=shown.Count.ToString("N0")+" covered entries · edits never overwrite native data or get replaced by model output";SelectRow();}
 void SelectRow(){if(grid.CurrentCell==null||grid.CurrentCell.RowIndex>=shown.Count)return;current=shown[grid.CurrentCell.RowIndex];save.Enabled=reset.Enabled=current.Context=="EnglishCoverage";source.Text=current.Source;target.Text=Target(current);LocalEdit edit;edits.TryGetValue(current.Key,out edit);original.Checked=edit!=null&&edit.LeaveOriginal;defer.Checked=edit!=null&&edit.Deferred;status.Text=State(current)+" · "+current.Category+" · "+current.Context+(failures.ContainsKey(current.Key)?" · "+failures[current.Key]:"");}
 async Task Save(bool clear){if(busy||current==null)return;var row=current;busy=true;save.Enabled=reset.Enabled=false;var edit=new LocalEdit{Key=row.Key,Source=row.Source,Category=row.Category,Context=row.Context,Target=clear?null:target.Text,LeaveOriginal=!clear&&original.Checked,Deferred=!clear&&defer.Checked};try{if(edit.Target!=null&&string.IsNullOrWhiteSpace(edit.Target)&&!edit.LeaveOriginal&&!edit.Deferred)throw new IOException("Enter a translation or choose Leave original / Defer.");await Task.Run(()=>LocalTranslation.Edit(run.Id,edit));edits=LocalTranslation.Edits(run.Id);status.Text="Saved · manual overrides take precedence; redraw the game window to see the change";grid.Invalidate();}catch(Exception e){status.Text=e.Message;}finally{busy=false;save.Enabled=reset.Enabled=true;}}
}
public static class LocalTextBoxHint {
 [System.Runtime.InteropServices.DllImport("user32.dll",CharSet=System.Runtime.InteropServices.CharSet.Unicode)]static extern IntPtr SendMessage(IntPtr window,int message,IntPtr parameter,string text);
 public static void PlaceholderTextCompat(this TextBox box,string text){box.AccessibleName=text;box.HandleCreated+=delegate{SendMessage(box.Handle,0x1501,new IntPtr(1),text);};}
}
